<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\Event; use Illuminate\Http\Request;
class EventController extends Controller { public function index(){return Event::where('date','>=',now()->toDateString())->orderBy('date')->get();} public function store(Request $r){$d=$r->validate(['title'=>'required|max:60','date'=>'required|date','venue'=>'nullable|max:80','desc'=>'nullable|max:300']); return Event::create($d);} public function show(Event $event){return $event;} public function update(Request $r,Event $event){$event->update($r->validate(['title'=>'sometimes|max:60','date'=>'sometimes|date','venue'=>'nullable|max:80','desc'=>'nullable|max:300'])); return $event;} public function destroy(Event $event){$event->delete(); return response()->noContent();} }
